{
  "tasks": [
    {
      "task_id": "T01",
      "title": "上海与杭州薪资元平均值对比及排名",
      "business_question": "比较上海与杭州的薪资元平均值，并按该指标降序排名。",
      "priority": "P0",
      "priority_reason": "删除此任务将无法回答核心问题（城市薪资均值对比）或支持核心决策（基于均值的排名）。这是唯一直接满足所有核心需求C01-C04的任务。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0001",
                "operator": "in",
                "value": [
                  "上海",
                  "杭州"
                ]
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "salary_avg"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "sort",
          "params": {
            "field": "salary_avg",
            "direction": "desc"
          }
        }
      ]
    }
  ]
}
